from dataclasses import dataclass
from pathlib import Path

@dataclass
class Cfg:
    root: Path

def banner(c: Cfg) -> str:
    return f"root={c.root / 'data'}"

function handle(data: unknown) {
  const user = data as { id: string };
  return user.id;
}

type Shape = { kind: 'a'; a: number } | { kind: 'b'; b: number };
function area(s: Shape): number {
  switch (s.kind) {
    case 'a': return s.a;
    case 'b': return s.b;
    default: { const _x: never = s; return _x; }
  }
}

func count(s string) int {
